 @page "/notepad"
 @rendermode InteractiveServer
 @inject IJSRuntime JS
 @implements IAsyncDisposable

 <PageTitle>Notepad</PageTitle>

 <h3>Notepad</h3>

 <textarea @bind="Content" @bind:event="oninput" @bind:after="OnContentChangedAsync" rows="15" class="form-control mb-3"></textarea>

 <div class="d-flex align-items-center gap-3 mb-3">
     <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
     <button class="btn btn-danger" @onclick="ClearAsync">Clear</button>
     @if (_lastSavedAt is not null)
     {
         <span class="text-muted">Last saved at @_lastSavedAt.Value.ToString("HH:mm:ss")</span>
     }
 </div>

 @code {
     private string Content { get; set; } = string.Empty;
     private string _savedContent = string.Empty;
     private DateTime? _lastSavedAt;
     private NotepadInterop? _interop;
     private DotNetObjectReference<Notepad>? _dotNetRef;
     private Timer? _autoSaveTimer;

     protected override void OnInitialized()
     {
         _autoSaveTimer = new Timer(AutoSaveCallback, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
     }

     protected override async Task OnAfterRenderAsync(bool firstRender)
     {
         if (firstRender)
         {
             _interop = new NotepadInterop(JS);
             _dotNetRef = DotNetObjectReference.Create(this);
             await _interop.InitializeAsync(_dotNetRef);

             Content = await _interop.LoadContentAsync();
             _savedContent = Content;
             StateHasChanged();
         }
     }

     private async void AutoSaveCallback(object? state)
     {
         await InvokeAsync(async () =>
         {
             if (_interop is not null && Content != _savedContent)
             {
                 await SaveContentInternalAsync();
                 StateHasChanged();
             }
         });
     }

     private async Task SaveNowAsync()
     {
         if (_interop is not null)
         {
             await SaveContentInternalAsync();
         }
     }

     private async Task SaveContentInternalAsync()
     {
         await _interop!.SaveContentAsync(Content);
         _savedContent = Content;
         _lastSavedAt = DateTime.Now;
         await _interop.DisableBeforeUnloadAsync();
     }

     private async Task ClearAsync()
     {
         if (_interop is not null)
         {
             Content = string.Empty;
             _savedContent = string.Empty;
             _lastSavedAt = null;
             await _interop.ClearContentAsync();
             await _interop.DisableBeforeUnloadAsync();
         }
     }

     private async Task OnContentChangedAsync()
     {
         if (_interop is null) return;

         if (Content != _savedContent)
             await _interop.EnableBeforeUnloadAsync();
         else
             await _interop.DisableBeforeUnloadAsync();
     }

     public async ValueTask DisposeAsync()
     {
         _autoSaveTimer?.Dispose();

         if (_interop is not null)
             await _interop.DisposeAsync();

         _dotNetRef?.Dispose();
     }
 }
